mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
c1.C_Name_History as envContractorNameHistory, c1.C_Name as envContractorName, c1.C_Abbreviation as envContrAbbName, mn.* from Con_En_Verify mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Env_Contractor_Id=c1.C_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Env_Create_Time desc
